document.addEventListener("DOMContentLoaded",()=>{window.mobileMenuObject=new MobileMenu;new SwiperManager;new Menu;new PartnersManager;new FieldsHandler;window.ModalObject=new Modal;const forms=document.querySelectorAll("form");forms.forEach(form=>{new FormHandler(form)});document.querySelectorAll(".header__callback-phones-inner").forEach(dropdown=>{const arrow=dropdown.querySelector(".arrow");const secondaryPhone=dropdown.querySelector(".white-link.hidden");if(arrow&&secondaryPhone){arrow.addEventListener("click",()=>{secondaryPhone.classList.toggle("hidden");arrow.classList.toggle("rotated")})}})});